{"file_path": "repo/game/src/config.js", "content": "// config.js — every tuning number and colour for Turkey Run: The Great Escape.
// One place to tune the run: speed, gravity, stages, scoring and the palette.
export const CANVAS_W = 960;
export const CANVAS_H = 540;
export const GROUND_Y = 470;

export const TURKEY_X = 180;
export const TURKEY_W = 56;
export const TURKEY_H_STAND = 64;
export const TURKEY_H_DUCK = 38;

export const GRAVITY = 2300;
export const JUMP_VELOCITY = -820;
export const BASE_SPEED = 250;
export const SPEED_PER_100M = 16;
export const MAX_SPEED = 540;
export const METERS_PER_PX = 1 / 50;

export const ESCAPE_DISTANCE_M = 1500;
export const START_LIVES = 3;
export const FARMER_GAP_START = 260;
export const FARMER_GAP_MIN = 0;
export const FARMER_GAP_MAX = 420;
export const FARMER_CREEP_PER_S = 5;
export const STUMBLE_GAP_COST = 62;
export const STUMBLE_LIVES_COST = 1;
export const CORN_GAP_BONUS = 4;
export const HIDE_GAP_BONUS = 70;
export const HIDE_SCORE_BONUS = 50;

export const SCORE_PER_METER = 10;
export const SCORE_PER_CORN = 25;

export const STAGES = [
  { name: 'The Farmyard', fromM: 0, toM: 500, sky: '#f7c873', horizon: '#e89b4d', ground: '#a9713a', grass: '#7fae4e', accent: '#c96f2e' },
  { name: 'The Orchard', fromM: 500, toM: 1000, sky: '#f2a65e', horizon: '#d97b3f', ground: '#96602c', grass: '#6d9c3f', accent: '#b8452a' },
  { name: 'The Kitchen', fromM: 1000, toM: 1500, sky: '#e88a4f', horizon: '#c25a33', ground: '#7d4a26', grass: '#5d7f33', accent: '#8f2f1d' },
];

export const PALETTE = {
  turkeyBody: '#8a5a2b',
  turkeyWing: '#6e4520',
  turkeyHead: '#a06a33',
  turkeyFeather: ['#b4552d', '#d97b2f', '#e8a83c', '#7d4a1e', '#c96f2e'],
  turkeyBeak: '#e8a83c',
  turkeyWattle: '#c0392b',
  farmerShirt: '#4a6fa5',
  farmerOveralls: '#3b5a8a',
  farmerSkin: '#e8b98a',
  farmerHat: '#8a6d3b',
  corn: '#f2c230',
  cornHusk: '#7fae4e',
  knifeBlade: '#dfe6ea',
  knifeHandle: '#5b3a1e',
  ovenBody: '#5b5b66',
  ovenGlow: '#ff7a2f',
  hudPanel: 'rgba(46, 26, 10, 0.72)',
  hudText: '#ffe9b8',
  titleText: '#fff3d6',
};

export function stageFor(distanceM) {
  for (const stage of STAGES) {
    if (distanceM < stage.toM) return stage;
  }
  return STAGES[STAGES.length - 1];
}

export function speedFor(distanceM) {
  return Math.min(MAX_SPEED, BASE_SPEED + Math.floor(distanceM / 100) * SPEED_PER_100M);
}
"}

{"file_path": "repo/game/src/random.js", "content": "// random.js — a tiny seeded RNG (mulberry32) so posed screenshot scenes and
// spawn patterns are reproducible from a seed.
export function mulberry32(seed) {
  let a = seed >>> 0;
  return function next() {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function pick(rng, list) {
  return list[Math.floor(rng() * list.length)];
}

export function range(rng, min, max) {
  return min + rng() * (max - min);
}
"}

{"file_path": "repo/game/src/input.js", "content": "// input.js — keyboard and mouse/pointer input for the turkey.
// Arrow keys / Space jump, Down/S duck and hide, R restart, P pause, M mute.
// Clicking (or tapping) the canvas also jumps. Nothing here touches the network.
export function createInput(canvas) {
  const state = {
    jumpPressed: false,
    jumpHeld: false,
    duckHeld: false,
    restartPressed: false,
    pausePressed: false,
    mutePressed: false,
    anyPressed: false,
    pointerX: 0,
    pointerY: 0,
  };

  function onKeyDown(event) {
    const key = event.key;
    if (key === ' ' || key === 'ArrowUp' || key === 'w' || key === 'W') {
      if (!event.repeat) state.jumpPressed = true;
      state.jumpHeld = true;
      state.anyPressed = true;
      event.preventDefault();
    } else if (key === 'ArrowDown' || key === 's' || key === 'S') {
      state.duckHeld = true;
      state.anyPressed = true;
      event.preventDefault();
    } else if (key === 'r' || key === 'R') {
      state.restartPressed = true;
      state.anyPressed = true;
    } else if (key === 'p' || key === 'P') {
      state.pausePressed = true;
    } else if (key === 'm' || key === 'M') {
      state.mutePressed = true;
    } else if (key === 'Enter') {
      state.anyPressed = true;
    }
  }

  function onKeyUp(event) {
    const key = event.key;
    if (key === ' ' || key === 'ArrowUp' || key === 'w' || key === 'W') state.jumpHeld = false;
    if (key === 'ArrowDown' || key === 's' || key === 'S') state.duckHeld = false;
  }

  function onPointerDown(event) {
    const rect = canvas.getBoundingClientRect();
    state.pointerX = event.clientX - rect.left;
    state.pointerY = event.clientY - rect.top;
    state.jumpPressed = true;
    state.anyPressed = true;
  }

  window.addEventListener('keydown', onKeyDown);
  window.addEventListener('keyup', onKeyUp);
  canvas.addEventListener('pointerdown', onPointerDown);

  // Edge-triggered flags are consumed once per frame by the game loop.
  state.consume = function consume() {
    const pressed = {
      jump: state.jumpPressed,
      restart: state.restartPressed,
      pause: state.pausePressed,
      mute: state.mutePressed,
      any: state.anyPressed,
    };
    state.jumpPressed = false;
    state.restartPressed = false;
    state.pausePressed = false;
    state.mutePressed = false;
    state.anyPressed = false;
    return pressed;
  };

  return state;
}
"}

{"file_path": "repo/game/src/audio.js", "content": "// audio.js — every sound is synthesized with WebAudio: no audio files, no network.
// A gobble, a jump whoosh, a corn chime, a thud, the farmer's shout, and short
// jingles for escape and capture. Created lazily on first user gesture.
export class SoundEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.musicTimer = null;
  }

  ensure() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AudioContext = window.AudioContext || window.webkitAudioContext;
    if (!AudioContext) return;
    this.ctx = new AudioContext();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.35;
    this.master.connect(this.ctx.destination);
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master) this.master.gain.value = muted ? 0 : 0.35;
  }

  tone(freq, dur, type, vol, when = 0, slideTo = null) {
    if (!this.ctx || this.muted) return;
    const t0 = this.ctx.currentTime + when;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (slideTo !== null) osc.frequency.exponentialRampToValueAtTime(Math.max(20, slideTo), t0 + dur);
    gain.gain.setValueAtTime(0, t0);
    gain.gain.linearRampToValueAtTime(vol, t0 + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.001, t0 + dur);
    osc.connect(gain);
    gain.connect(this.master);
    osc.start(t0);
    osc.stop(t0 + dur + 0.05);
  }

  noise(dur, vol, when = 0, lowpass = 1200) {
    if (!this.ctx || this.muted) return;
    const t0 = this.ctx.currentTime + when;
    const len = Math.max(1, Math.floor(this.ctx.sampleRate * dur));
    const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / len);
    const src = this.ctx.createBufferSource();
    src.buffer = buffer;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = lowpass;
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(vol, t0);
    gain.gain.exponentialRampToValueAtTime(0.001, t0 + dur);
    src.connect(filter);
    filter.connect(gain);
    gain.connect(this.master);
    src.start(t0);
  }

  gobble() {
    // Two quick descending clucks, the turkey's own voice.
    this.tone(520, 0.09, 'square', 0.22, 0, 340);
    this.tone(430, 0.09, 'square', 0.22, 0.11, 280);
    this.tone(360, 0.14, 'square', 0.2, 0.23, 220);
  }

  jump() {
    this.noise(0.16, 0.14, 0, 2600);
    this.tone(300, 0.16, 'sine', 0.12, 0, 620);
  }

  corn() {
    this.tone(880, 0.09, 'sine', 0.2);
    this.tone(1318, 0.14, 'sine', 0.18, 0.07);
  }

  thud() {
    this.noise(0.18, 0.3, 0, 500);
    this.tone(120, 0.2, 'sine', 0.3, 0, 55);
  }

  hide() {
    this.tone(660, 0.08, 'triangle', 0.16);
    this.tone(990, 0.12, 'triangle', 0.16, 0.08);
  }

  farmerShout() {
    this.tone(180, 0.28, 'sawtooth', 0.25, 0, 90);
    this.tone(150, 0.2, 'sawtooth', 0.2, 0.3, 80);
  }

  spotted() {
    this.tone(740, 0.1, 'square', 0.18);
    this.tone(740, 0.1, 'square', 0.18, 0.13);
  }

  escapeFanfare() {
    const notes = [523, 659, 784, 1047, 784, 1047];
    notes.forEach((freq, i) => this.tone(freq, 0.22, 'triangle', 0.22, i * 0.14));
  }

  caughtLament() {
    const notes = [392, 370, 349, 311];
    notes.forEach((freq, i) => this.tone(freq, 0.3, 'sawtooth', 0.16, i * 0.22));
  }

  click() {
    this.tone(700, 0.05, 'sine', 0.14);
  }
}
"}

{"file_path": "repo/game/src/turkey.js", "content": "// turkey.js — the player: a turkey called Gobbles, drawn in canvas code.
// Physics (jump, duck, stumble, run cycle) and the turkey's own drawing live here.
import {
  GROUND_Y, GRAVITY, JUMP_VELOCITY, TURKEY_H_STAND, TURKEY_H_DUCK, TURKEY_W, PALETTE,
} from './config.js';

export function createTurkey() {
  return {
    x: 180,
    y: GROUND_Y,
    vy: 0,
    ducking: false,
    stumbling: 0,
    runPhase: 0,
    grounded: true,
  };
}

export function turkeyHeight(turkey) {
  return turkey.ducking ? TURKEY_H_DUCK : TURKEY_H_STAND;
}

export function turkeyHitbox(turkey) {
  const h = turkeyHeight(turkey);
  return { x: turkey.x - TURKEY_W / 2 + 6, y: turkey.y - h, w: TURKEY_W - 12, h };
}

export function updateTurkey(turkey, input, dt) {
  turkey.ducking = input.duckHeld && turkey.grounded;
  if (input.jump && turkey.grounded && turkey.stumbling <= 0) {
    turkey.vy = JUMP_VELOCITY;
    turkey.grounded = false;
    turkey.ducking = false;
  }
  if (turkey.stumbling > 0) turkey.stumbling -= dt;
  turkey.vy += GRAVITY * dt;
  turkey.y += turkey.vy * dt;
  if (turkey.y >= GROUND_Y) {
    turkey.y = GROUND_Y;
    turkey.vy = 0;
    turkey.grounded = true;
  }
  turkey.runPhase += dt * (turkey.grounded ? 14 : 4);
}

export function stumbleTurkey(turkey) {
  turkey.stumbling = 0.55;
  turkey.vy = Math.min(turkey.vy, -260);
  turkey.grounded = false;
}

// Draw the turkey facing right, mid-run. All art is code: a fan tail, a round
// body, a head with beak and wattle, and legs that cycle with runPhase.
export function drawTurkey(ctx, turkey, time) {
  const h = turkeyHeight(turkey);
  const cx = turkey.x;
  const feetY = turkey.y;
  const bodyY = feetY - h * 0.55;
  const flash = turkey.stumbling > 0 && Math.floor(time * 14) % 2 === 0;
  ctx.save();
  if (flash) ctx.globalAlpha = 0.45;

  // Tail fan: five feathers fanning out behind the body.
  const fan = turkey.ducking ? 0.55 : 1;
  for (let i = -2; i <= 2; i++) {
    const angle = -Math.PI / 2 + (i * 0.42 * fan);
    const len = 34 * fan;
    const fx = cx - 14 + Math.cos(angle) * len;
    const fy = bodyY - 6 + Math.sin(angle) * len;
    ctx.strokeStyle = PALETTE.turkeyFeather[i + 2];
    ctx.lineWidth = 9;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(cx - 12, bodyY - 4);
    ctx.lineTo(fx, fy);
    ctx.stroke();
  }

  // Legs, cycling while running.
  const step = Math.sin(turkey.runPhase) * (turkey.grounded ? 9 : 3);
  ctx.strokeStyle = '#e8a83c';
  ctx.lineWidth = 4;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(cx - 6, feetY - 14);
  ctx.lineTo(cx - 6 + step, feetY);
  ctx.moveTo(cx + 6, feetY - 14);
  ctx.lineTo(cx + 6 - step, feetY);
  ctx.stroke();

  // Body.
  ctx.fillStyle = PALETTE.turkeyBody;
  ctx.beginPath();
  ctx.ellipse(cx, bodyY, 26, h * 0.42, 0, 0, Math.PI * 2);
  ctx.fill();
  // Wing.
  ctx.fillStyle = PALETTE.turkeyWing;
  ctx.beginPath();
  ctx.ellipse(cx - 2, bodyY + 2, 15, 10, -0.35, 0, Math.PI * 2);
  ctx.fill();

  // Neck and head, lowered when ducking.
  const headY = turkey.ducking ? bodyY - 8 : bodyY - h * 0.42 - 12;
  const headX = cx + 16;
  ctx.strokeStyle = PALETTE.turkeyHead;
  ctx.lineWidth = 9;
  ctx.beginPath();
  ctx.moveTo(cx + 12, bodyY - 8);
  ctx.lineTo(headX, headY + 4);
  ctx.stroke();
  ctx.fillStyle = PALETTE.turkeyHead;
  ctx.beginPath();
  ctx.arc(headX, headY, 11, 0, Math.PI * 2);
  ctx.fill();
  // Beak.
  ctx.fillStyle = PALETTE.turkeyBeak;
  ctx.beginPath();
  ctx.moveTo(headX + 8, headY - 2);
  ctx.lineTo(headX + 22, headY + 3);
  ctx.lineTo(headX + 8, headY + 7);
  ctx.closePath();
  ctx.fill();
  // Wattle.
  ctx.fillStyle = PALETTE.turkeyWattle;
  ctx.beginPath();
  ctx.ellipse(headX + 12, headY + 9, 4, 6, 0.3, 0, Math.PI * 2);
  ctx.fill();
  // Eye.
  ctx.fillStyle = '#1c1410';
  ctx.beginPath();
  ctx.arc(headX + 3, headY - 3, 2.6, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}
"}

{"file_path": "repo/game/src/farmer.js", "content": "// farmer.js — the chaser: Farmer Bram, drawn in canvas code.
// He starts a gap behind the turkey and gains ground whenever the turkey
// stumbles; corn and hiding push him back. Gap 0 means caught.
import { GROUND_Y, FARMER_GAP_START, PALETTE } from './config.js';

export function createFarmer() {
  return {
    gap: FARMER_GAP_START,
    runPhase: 0,
    state: 'chasing', // chasing | searching | grabbing | celebrating
    shoutTimer: 0,
  };
}

// The farmer's screen x follows the gap: the smaller the gap, the closer he is.
export function farmerX(farmer, turkeyX) {
  return turkeyX - 70 - farmer.gap * 0.55;
}

export function updateFarmer(farmer, dt, creepPerS) {
  farmer.runPhase += dt * 13;
  farmer.gap = Math.max(0, farmer.gap - creepPerS * dt);
  if (farmer.shoutTimer > 0) farmer.shoutTimer -= dt;
}

export function farmerShout(farmer) {
  farmer.shoutTimer = 0.9;
}

// Draw Farmer Bram: straw hat, red-checked shirt under overalls, long arms
// reaching for the turkey, boots pounding the dirt.
export function drawFarmer(ctx, farmer, turkeyX, time) {
  const x = farmerX(farmer, turkeyX);
  if (x < -90) return; // off-screen left, still a threat on the meter
  const feetY = GROUND_Y;
  const step = Math.sin(farmer.runPhase) * 10;
  const bob = Math.abs(Math.sin(farmer.runPhase)) * 3;
  const bodyY = feetY - 52 - bob;
  ctx.save();

  // Legs.
  ctx.strokeStyle = PALETTE.farmerOveralls;
  ctx.lineWidth = 9;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(x - 6, bodyY + 22);
  ctx.lineTo(x - 10 + step, feetY);
  ctx.moveTo(x + 6, bodyY + 22);
  ctx.lineTo(x + 10 - step, feetY);
  ctx.stroke();
  // Boots.
  ctx.fillStyle = '#4a2f1d';
  ctx.fillRect(x - 16 + step, feetY - 6, 14, 6);
  ctx.fillRect(x + 4 - step, feetY - 6, 14, 6);

  // Overalls body.
  ctx.fillStyle = PALETTE.farmerOveralls;
  ctx.fillRect(x - 16, bodyY - 6, 32, 34);
  // Shirt sleeves and reaching arms.
  const reach = farmer.state === 'grabbing' ? 26 : 14 + Math.sin(farmer.runPhase) * 4;
  ctx.strokeStyle = PALETTE.farmerShirt;
  ctx.lineWidth = 8;
  ctx.beginPath();
  ctx.moveTo(x + 12, bodyY + 2);
  ctx.lineTo(x + 24 + reach, bodyY + 8 - Math.sin(farmer.runPhase) * 4);
  ctx.moveTo(x + 10, bodyY + 12);
  ctx.lineTo(x + 22 + reach * 0.8, bodyY + 22);
  ctx.stroke();
  // Shirt chest.
  ctx.fillStyle = '#b8452a';
  ctx.fillRect(x - 16, bodyY - 6, 32, 12);

  // Head.
  ctx.fillStyle = PALETTE.farmerSkin;
  ctx.beginPath();
  ctx.arc(x + 2, bodyY - 18, 13, 0, Math.PI * 2);
  ctx.fill();
  // Moustache.
  ctx.fillStyle = '#5b3a1e';
  ctx.fillRect(x - 6, bodyY - 14, 16, 4);
  // Straw hat.
  ctx.fillStyle = PALETTE.farmerHat;
  ctx.beginPath();
  ctx.ellipse(x + 2, bodyY - 28, 20, 6, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillRect(x - 10, bodyY - 40, 24, 13);
  // Shout burst.
  if (farmer.shoutTimer > 0) {
    ctx.fillStyle = '#fff3d6';
    ctx.font = 'bold 15px Georgia, serif';
    ctx.textAlign = 'left';
    ctx.fillText('COME BACK HERE!', x + 26, bodyY - 46);
  }
  ctx.restore();
}
"}

{"file_path": "repo/game/src/world.js", "content": "// world.js — the run itself: spawning, collisions, scoring and stages.
// Pure logic over a plain state object, so the rules can be tested without a canvas.
import {
  CANVAS_W, GROUND_Y, ESCAPE_DISTANCE_M, START_LIVES, FARMER_GAP_START,
  FARMER_GAP_MAX, FARMER_CREEP_PER_S, STUMBLE_GAP_COST, CORN_GAP_BONUS,
  HIDE_GAP_BONUS, HIDE_SCORE_BONUS, SCORE_PER_METER, SCORE_PER_CORN,
  stageFor, speedFor,
} from './config.js';
import { mulberry32, range } from './random.js';
import { turkeyHitbox, stumbleTurkey } from './turkey.js';

export function createWorld(seed = 20261127) {
  return {
    seed,
    rng: mulberry32(seed),
    distanceM: 0,
    score: 0,
    cornCollected: 0,
    lives: START_LIVES,
    farmerGap: FARMER_GAP_START,
    obstacles: [],
    corns: [],
    haystacks: [],
    spawnIn: 420,
    hiddenFlash: 0,
    banner: null,
    bannerTimer: 0,
    stage: stageFor(0),
    over: null, // null | 'caught' | 'escaped'
    overReason: '',
    elapsed: 0,
  };
}

function spawnPattern(world) {
  const d = world.distanceM;
  const stageIndex = d < 500 ? 0 : d < 1000 ? 1 : 2;
  const r = world.rng;
  const x = CANVAS_W + 60;
  const roll = r();
  if (stageIndex === 0) {
    if (roll < 0.34) addObstacle(world, 'fence', x);
    else if (roll < 0.58) addObstacle(world, 'haybale', x);
    else if (roll < 0.74) addObstacle(world, 'puddle', x);
    else if (roll < 0.9) addHaystack(world, x);
    else addCornRow(world, x, 3);
  } else if (stageIndex === 1) {
    if (roll < 0.28) addObstacle(world, 'fence', x);
    else if (roll < 0.42) addObstacle(world, 'haybale', x);
    else if (roll < 0.58) addObstacle(world, 'puddle', x);
    else if (roll < 0.72) addObstacle(world, 'knifeSwing', x);
    else if (roll < 0.86) addHaystack(world, x);
    else addCornRow(world, x, 4);
  } else {
    if (roll < 0.26) addObstacle(world, 'oven', x);
    else if (roll < 0.5) addObstacle(world, 'knifeSwing', x);
    else if (roll < 0.64) addObstacle(world, 'knifeRoll', x);
    else if (roll < 0.78) addObstacle(world, 'fence', x);
    else if (roll < 0.9) addHaystack(world, x);
    else addCornRow(world, x, 4);
  }
  // Next gap shrinks as the run gets faster.
  const base = 430 - Math.min(170, d * 0.14);
  world.spawnIn = base + range(r, 0, 190);
}

function addObstacle(world, kind, x) {
  const dims = {
    fence: { w: 26, h: 74 },
    haybale: { w: 50, h: 48 },
    puddle: { w: 96, h: 16 },
    oven: { w: 74, h: 112 },
    knifeSwing: { w: 22, h: 74 },
    knifeRoll: { w: 64, h: 26 },
  }[kind];
  world.obstacles.push({ kind, x, w: dims.w, h: dims.h, hit: false, swing: world.rng() * Math.PI * 2 });
}

function addHaystack(world, x) {
  world.haystacks.push({ x, w: 76, h: 84, used: false });
}

function addCornRow(world, x, count) {
  for (let i = 0; i < count; i++) {
    world.corns.push({
      x: x + i * 46,
      y: GROUND_Y - 66 - (i % 2) * 34,
      taken: false,
      bob: world.rng() * Math.PI * 2,
    });
  }
}

function obstacleRect(ob) {
  if (ob.kind === 'knifeSwing') {
    // The blade hangs low across the turkey's head height: a standing turkey
    // runs into it, a ducking turkey (38 px tall) slips underneath.
    return { x: ob.x, y: GROUND_Y - 72, w: ob.w, h: 30 };
  }
  return { x: ob.x, y: GROUND_Y - ob.h, w: ob.w, h: ob.h };
}

export function rectsOverlap(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}

// One fixed step of the run. Returns events for sound/feedback.
export function updateWorld(world, turkey, farmer, dt) {
  const events = [];
  if (world.over) return events;
  world.elapsed += dt;
  const speed = speedFor(world.distanceM);
  world.distanceM += speed * dt * (1 / 50);
  world.score += speed * dt * (1 / 50) * SCORE_PER_METER;
  world.farmerGap = Math.max(0, world.farmerGap - FARMER_CREEP_PER_S * dt);

  const stage = stageFor(world.distanceM);
  if (stage !== world.stage) {
    world.stage = stage;
    world.banner = stage.name;
    world.bannerTimer = 2.2;
    events.push('stage');
  }
  if (world.bannerTimer > 0) world.bannerTimer -= dt;
  if (world.hiddenFlash > 0) world.hiddenFlash -= dt;

  world.spawnIn -= speed * dt;
  if (world.spawnIn <= 0) spawnPattern(world);

  const move = speed * dt;
  for (const ob of world.obstacles) ob.x -= move;
  for (const corn of world.corns) corn.x -= move;
  for (const hay of world.haystacks) hay.x -= move;
  world.obstacles = world.obstacles.filter((ob) => ob.x + ob.w > -80);
  world.corns = world.corns.filter((c) => c.x > -40);
  world.haystacks = world.haystacks.filter((h) => h.x + h.w > -80);

  const box = turkeyHitbox(turkey);
  for (const ob of world.obstacles) {
    if (ob.hit) continue;
    if (rectsOverlap(box, obstacleRect(ob))) {
      ob.hit = true;
      world.lives -= 1;
      world.farmerGap = Math.max(0, world.farmerGap - STUMBLE_GAP_COST);
      stumbleTurkey(turkey);
      events.push('stumble');
      if (world.lives <= 0) {
        world.over = 'caught';
        world.overReason = 'Gobbles tripped one too many times — Farmer Bram caught up.';
      }
      break;
    }
  }

  for (const corn of world.corns) {
    if (!corn.taken && rectsOverlap(box, { x: corn.x - 14, y: corn.y - 14, w: 28, h: 28 })) {
      corn.taken = true;
      world.cornCollected += 1;
      world.score += SCORE_PER_CORN;
      world.farmerGap = Math.min(FARMER_GAP_MAX, world.farmerGap + CORN_GAP_BONUS);
      events.push('corn');
    }
  }
  world.corns = world.corns.filter((c) => !c.taken);

  for (const hay of world.haystacks) {
    if (hay.used) continue;
    const hayRect = { x: hay.x, y: GROUND_Y - hay.h, w: hay.w, h: hay.h };
    if (rectsOverlap(box, hayRect)) {
      hay.used = true;
      if (turkey.ducking) {
        world.farmerGap = Math.min(FARMER_GAP_MAX, world.farmerGap + HIDE_GAP_BONUS);
        world.score += HIDE_SCORE_BONUS;
        world.hiddenFlash = 1.4;
        events.push('hide');
      } else {
        world.lives -= 1;
        world.farmerGap = Math.max(0, world.farmerGap - STUMBLE_GAP_COST);
        stumbleTurkey(turkey);
        events.push('stumble');
        if (world.lives <= 0) {
          world.over = 'caught';
          world.overReason = 'Gobbles crashed into a haystack — Farmer Bram caught up.';
        }
      }
    }
  }

  if (!world.over && world.farmerGap <= 0) {
    world.over = 'caught';
    world.overReason = 'Farmer Bram caught Gobbles by the tail feathers!';
    events.push('caught');
  }
  if (!world.over && world.distanceM >= ESCAPE_DISTANCE_M) {
    world.over = 'escaped';
    world.overReason = 'Gobbles reached Freedom Woods — no Thanksgiving dinner today!';
    events.push('escaped');
  }
  return events;
}

export function finalScore(world) {
  return Math.floor(world.score);
}
